entries.search:
version Read the upstream node version. {
  "jsonrpc": "2.0",
  "method": "version",
  "params": {},
  "id": 1
} {
  "result": {
    "rpc_version": "<string>"
  }
}

block_count Read upstream ledger block counts. {
  "jsonrpc": "2.0",
  "method": "block_count",
  "params": {},
  "id": 1
} {
  "result": {
    "cemented": "<string>",
    "count": "<string>",
    "unchecked": "<string>"
  }
}

account_info Read current and confirmed frontier state for one account. {
  "jsonrpc": "2.0",
  "method": "account_info",
  "params": {
    "account": "<account>"
  },
  "id": 1
} {
  "result": {
    "balance": "<string>",
    "confirmation_height": "<string>",
    "confirmation_height_frontier": "<string | null>",
    "confirmed_balance": "<string>",
    "confirmed_frontier": "<string | null>",
    "frontier": "<string | null>",
    "open_block": "<string | null>",
    "opened": "<boolean>",
    "representative_block": "<string | null>"
  }
}

receivable Read receivable blocks for an account. {
  "jsonrpc": "2.0",
  "method": "receivable",
  "params": {
    "account": "<account>"
  },
  "id": 1
} {
  "result": [
    {
      "amount": "<string>",
      "hash": "<string>",
      "source": "<string>"
    }
  ]
}

account_balance Read balance and receivable state for one account. {
  "jsonrpc": "2.0",
  "method": "account_balance",
  "params": {
    "account": "<account>"
  },
  "id": 1
} {
  "result": {
    "balance": "<string>",
    "receivable": "<string>"
  }
}

accounts_balances Read balances and receivables for several accounts. {
  "jsonrpc": "2.0",
  "method": "accounts_balances",
  "params": {
    "accounts": [
      "<account>"
    ]
  },
  "id": 1
} {
  "result": {
    "balances": {
      "<key>": {
        "balance": "<string>",
        "receivable": "<string>"
      }
    },
    "errors": {
      "<key>": "<string>"
    }
  }
}

block_info Read block metadata and whether the block is cemented. {
  "jsonrpc": "2.0",
  "method": "block_info",
  "params": {
    "hash": "<hash>"
  },
  "id": 1
} {
  "result": {
    "amount": "<string>",
    "balance": "<string>",
    "block": {
      "<key>": "<value>"
    },
    "block_account": "<string>",
    "confirmed": "<boolean>",
    "hash": "<string>",
    "height": "<string>",
    "subtype": "<string>"
  }
}

blocks_info Read metadata for several blocks. {
  "jsonrpc": "2.0",
  "method": "blocks_info",
  "params": {
    "hashes": [
      "<hash>"
    ]
  },
  "id": 1
} {
  "result": {
    "blocks": {
      "<key>": {
        "amount": "<string>",
        "balance": "<string>",
        "block": {
          "<key>": "<value>"
        },
        "block_account": "<string>",
        "confirmed": "<boolean>",
        "hash": "<string>",
        "height": "<string>",
        "subtype": "<string>"
      }
    }
  }
}

process Submit a precomputed block and return its hash. {
  "jsonrpc": "2.0",
  "method": "process",
  "params": {
    "block": "<block>"
  },
  "id": 1
} {
  "result": {
    "hash": "<string>"
  }
}

